<template>
  <div class="commisRecord">
    <title-line :title="title" />
    <div class="commisRecord-content">
      <div class="recordBox">
        <div class="thead">
          <span>{{ $t('wdsr.wdsr13') }}</span>
          <span>{{ $t('wdsr.wdsr14') }}</span>
          <span>{{ $t('wdsr.wdsr15') }}</span>
        </div>
        <div class="tbody">

          <van-pull-refresh v-model="refreshing" :loading-text="$t('tzjl.tzjl50')" :pulling-text="$t('tzjl.tzjl51')" :loosing-text="$t('tzjl.tzjl52')" :finished-text="$t('tzjl.tzjl53')" @refresh="onRefresh">
            <van-list
              v-model="loading"
              :finished="finished"
              :loading-text="$t('tzjl.tzjl50')"
              finished-text=""
              @load="onLoad"
            >
              <is-empty v-if="recordList.length===0" />
              <div v-for="(item,index) in recordList" v-else :key="index" class="list">
                <span>{{ item.ctime.slice(0,16) }}</span>
                <span style="color:#FFBF23;font-family: HelveticaNeue-Bold;font-weight:700">{{ item.mons }}</span>
                <span :style="item.cstatus==='待审核'?'color:#eac88e':item.cstatus==='已发放'?'color:#58e433':''">{{ item.cstatus }}</span>
              </div>
            </van-list>
          </van-pull-refresh>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
import TitleLine from './modules/TitleLine'
import { record } from '@/api/user'
export default {
  components: {
    TitleLine
  },
  props: {
    currentValue: {
      type: String,
      default: '哈希一分大小'
    }
  },
  data() {
    return {
      title: this.$t('wdsr.wdsr32'),
      recordList: [
      ],
      loading: false,
      finished: false,
      refreshing: false,
      pageNum: 1,
      pageSize: 10,
      type: 2
    }
  },
  created() {
    if (this.$route.query.type === '1') {
      this.title = this.$t('wdsr.wdsr12')
    } else {
      this.title = this.$t('wdsr.wdsr32')
    }
    this.type = this.$route.query.type
  },
  methods: {
    // goMore() {
    //   this.$router.push({ path: '/rechargeRecord' })
    // }
    async onLoad() {
      const res = await record({ pages: this.pageNum, type: this.type })
      if (this.refreshing) {
        this.recordList = []
        this.refreshing = false
      }
      this.recordList = this.recordList.concat(res.datalist)
      this.loading = false
      this.pageNum++
      if (this.recordList.length >= Number(res.totalrow)) {
        this.finished = true
      }
    },
    onRefresh() {
      // 清空列表数据
      this.finished = false
      this.pageNum = 1
      this.refreshing = true
      // 重新加载数据
      // 将 loading 设置为 true，表示处于加载状态
      this.loading = true
      this.onLoad()
    }
  }

}
</script>
<style lang="less" scoped>
.commisRecord {
    min-height: 100vh;
    width: 100%;
    background: var(--inner-bg-color);
    background-size: 100% 100%;
    overflow: hidden;
    font-size: 24px;
    color: #fff;
    .commisRecord-content{
        padding:28px;
        .recordBox{
            background: none;
            border-radius: 26px;
            // display: flex;
            // padding: 40px 22px 42px;
            .thead{
                display: flex;
                align-items: center;
                margin-bottom: 10px;
                height: 80px;
                line-height: 80px;
                background: rgba(223,226,253,0.12);
                border-radius: 12px;
                font-family: PingFangSC-Semibold;
                font-size: 28px;
                color: rgba(242,239,255,0.75);
                letter-spacing: 0;
                font-weight: 600;
                span {
                    flex: 1;
                    font-size: 28px;
                    // font-weight: 700;
                    // color: #7987a7;
                    text-align: center;
                }
            }
            .tbody{
                height: 1252px;
                overflow: hidden auto;
                .list{
                    display: flex;
                    align-items: center;
                    min-height: 84px;
                    // border-bottom: 1px solid #283249;
                    // border-bottom-color: #283249;
                    // border-bottom-style: solid;
                    // border-bottom-width: 2px;
                    span {
                        font-family: PingFangSC-Medium;
                        display: inline-block;
                        flex: 1;
                        font-size: 24px;
                        text-align: center;
                        color: #fff;
                        word-break: break-all;
                        word-wrap: normal;
                    }
                }
            }
        }
    }
}
</style>
